(function render(ctx){
 const {root,params:p,subtitles:s,time:t,width,height}=ctx,canvas=root.querySelector('#captions');
 if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}
 const g=canvas.getContext('2d');g.clearRect(0,0,width,height);g.font='700 '+p.fontSize+'px '+JSON.stringify(p.font);g.textBaseline='middle';
 const active=s.at(t,s.tail),clamp=v=>Math.max(0,Math.min(1,v));
 // Only active cues are laid out; the runtime indexes the full transcript once.
 active.forEach((cue,ci)=>{
  const units=cue.words||cue.text.split(/\s+/).map(text=>({text,start:cue.start,end:cue.end}));
  let start=0;
  if(cue.words&&units.length>p.perBlock){let index=0;for(let i=0;i<units.length;i++)if(units[i].start<=t)index=i;start=Math.floor(index/p.perBlock)*p.perBlock;}
  const group=units.slice(start,start+p.perBlock),lines=[[]],maxWidth=width*.88,space=g.measureText(' ').width;
  let lineWidth=0;for(const w of group){const measured=g.measureText(w.text).width;if(lineWidth&&lineWidth+space+measured>maxWidth){lines.push([]);lineWidth=0;}lines.at(-1).push({w,measured});lineWidth+=(lineWidth?space:0)+measured;}
  // A long phrase remains complete in phrase mode, wrapping to the safe width.
  if(!cue.words&&units.length>p.perBlock){lines.length=0;lines.push([]);lineWidth=0;for(const w of units){const measured=g.measureText(w.text).width;if(lineWidth&&lineWidth+space+measured>maxWidth){lines.push([]);lineWidth=0;}lines.at(-1).push({w,measured});lineWidth+=(lineWidth?space:0)+measured;}}
  const alpha=t<cue.end?1:1-clamp((t-cue.end)/Math.max(.001,s.tail));
  const lineHeight=p.fontSize*1.25,baseY=height*p.position/100-(active.length-1-ci)*(lineHeight*lines.length+12);
  lines.forEach((line,li)=>{
   const total=line.reduce((n,v)=>n+v.measured,0)+space*Math.max(0,line.length-1),fit=Math.min(1,maxWidth/Math.max(1,total));
   let x=-total/2;g.save();g.translate(width/2,baseY+(li-(lines.length-1)/2)*lineHeight);g.scale(fit,fit);
   for(const {w,measured}of line){const on=t>=w.start&&t<w.end,progress=clamp((t-w.start)/.18);const size=p.animation==='Pop'?(t<w.start?.86:1+Math.sin(progress*Math.PI)*.12):1;
    g.save();g.globalAlpha=alpha;g.translate(x+measured/2,p.animation==='Drop'?(1-progress)*-p.fontSize*.4:0);g.scale(size,size);g.textAlign='center';g.lineJoin='round';g.lineWidth=p.outline;g.strokeStyle=p.outlineColor;g.fillStyle=on&&cue.words?p.activeColor:p.color;if(p.outline)g.strokeText(w.text,0,0);g.fillText(w.text,0,0);g.restore();x+=measured+space;
   }g.restore();
  });
 });
})(ctx);
